package postgres
import("context";"errors";"github.com/jackc/pgx/v5";"github.com/menerjangbadai/dashboard/internal/application";"github.com/menerjangbadai/dashboard/internal/domain")
func(s *Store) SaveLogin(ctx context.Context,f application.LoginRequest)error{
 tx,e:=s.Pool.Begin(ctx);if e!=nil{return e};defer tx.Rollback(ctx)
 if _,e=tx.Exec(ctx,"DELETE FROM oidc_login_requests WHERE expires_at<now()");e!=nil{return e}
 if _,e=tx.Exec(ctx,"INSERT INTO oidc_login_requests(state_hash,binding_hash,nonce,verifier,expires_at) VALUES($1,$2,$3,$4,$5)",f.StateHash,f.BindingHash,f.Nonce,f.Verifier,f.ExpiresAt);e!=nil{return e};return tx.Commit(ctx)
}
func(s *Store) ConsumeLogin(ctx context.Context,state,binding string)(application.LoginRequest,error){f:=application.LoginRequest{};e:=s.Pool.QueryRow(ctx,"DELETE FROM oidc_login_requests WHERE state_hash=$1 AND binding_hash=$2 AND expires_at>now() RETURNING state_hash,binding_hash,nonce,verifier,expires_at",state,binding).Scan(&f.StateHash,&f.BindingHash,&f.Nonce,&f.Verifier,&f.ExpiresAt);if errors.Is(e,pgx.ErrNoRows){e=domain.ErrUnauthorized};return f,e}
func(s *Store) CreateSession(ctx context.Context,i application.Identity,hash,oldHash string)error{
 tx,e:=s.Pool.Begin(ctx);if e!=nil{return e};defer tx.Rollback(ctx)
 var a domain.Actor
 rows,e:=tx.Query(ctx,`SELECT m.org_id::text,m.user_id::text,m.authz_revision FROM external_identities i JOIN users u ON u.id=i.user_id JOIN organization_members m ON m.user_id=u.id JOIN organizations o ON o.id=m.org_id JOIN user_roles r ON (r.org_id,r.user_id)=(m.org_id,m.user_id) WHERE i.issuer=$1 AND i.subject=$2 AND m.active AND o.active AND u.active FOR SHARE OF m,u,o,r`,i.Issuer,i.Subject);if e!=nil{return e};count:=0;for rows.Next(){count++;if e=rows.Scan(&a.OrgID,&a.UserID,&a.Revision);e!=nil{rows.Close();return e}};rows.Close();if e=rows.Err();e!=nil{return e};if count!=1{return domain.ErrForbidden}
 if _,e=tx.Exec(ctx,`INSERT INTO sessions(token_hash,org_id,user_id,authz_revision,idle_expires_at,absolute_expires_at) VALUES($1,$2,$3,$4,now()+interval '30 minutes',now()+interval '12 hours')`,hash,a.OrgID,a.UserID,a.Revision);e!=nil{return e}
 if oldHash!=""{if _,e=tx.Exec(ctx,"UPDATE sessions SET revoked_at=now() WHERE token_hash=$1 AND revoked_at IS NULL",oldHash);e!=nil{return e}}
 if e=audit(ctx,tx,a,"login.success",nil);e!=nil{return e};return tx.Commit(ctx)
}
func(s *Store) Session(ctx context.Context,hash string)(application.Session,error){v:=application.Session{};e:=s.Pool.QueryRow(ctx,`UPDATE sessions s SET idle_expires_at=least(s.absolute_expires_at,now()+interval '30 minutes') FROM organization_members m, users u, organizations o, user_roles r WHERE s.token_hash=$1 AND s.revoked_at IS NULL AND s.idle_expires_at>now() AND s.absolute_expires_at>now() AND (m.org_id,m.user_id)=(s.org_id,s.user_id) AND m.authz_revision=s.authz_revision AND m.active AND u.id=s.user_id AND u.active AND o.id=s.org_id AND o.active AND (r.org_id,r.user_id)=(s.org_id,s.user_id) RETURNING s.org_id::text,s.user_id::text,m.authz_revision,r.role_id,u.display_name,s.absolute_expires_at`,hash).Scan(&v.Actor.OrgID,&v.Actor.UserID,&v.Actor.Revision,&v.Actor.Role,&v.User.DisplayName,&v.AbsoluteExpiresAt);v.User.ID=v.Actor.UserID;v.User.Role=v.Actor.Role;if errors.Is(e,pgx.ErrNoRows){e=domain.ErrUnauthorized};return v,e}
func(s *Store) RevokeSession(ctx context.Context,hash string)error{tx,e:=s.Pool.Begin(ctx);if e!=nil{return e};defer tx.Rollback(ctx);a:=domain.Actor{};e=tx.QueryRow(ctx,"UPDATE sessions SET revoked_at=now() WHERE token_hash=$1 AND revoked_at IS NULL RETURNING org_id::text,user_id::text",hash).Scan(&a.OrgID,&a.UserID);if errors.Is(e,pgx.ErrNoRows){return nil};if e!=nil{return e};if e=audit(ctx,tx,a,"logout",nil);e!=nil{return e};return tx.Commit(ctx)}
